import {PLAZA,FURNITURE_BY_ID,furniturePose} from './housing-data.js';
// Transient play sessions are shared; the plaza layout itself is durably saved.
export class PlazaPlayStore{
 constructor(game){this.game=game;this.sessions=new Map();this.motions=new Map();}
 snapshot(){this.prune();return [...this.sessions.values()];}
 stop(id){const state=this.sessions.get(id);if(!state)return;this.sessions.delete(id);this.game.broadcast({...state,type:'plaza-play-state',active:false});}
 prune(now=Date.now()){const ids=new Set(this.game.houses.snapshots().plaza?.items.map(i=>i.id));for(const [id,state]of this.sessions)if(!ids.has(state.itemId)||now-state.updatedAt>15000)this.stop(id);}
 receiveBounce(entry,m,now){const p=entry.player,item=this.game.houses.snapshots().plaza?.items.find(i=>i.id===m.itemId),f=item&&FURNITURE_BY_ID.get(item.t);if(f?.design!=='trampoline'||now-(entry.lastBounce||0)<350)return;const pose=furniturePose(item);if(Math.hypot(p.x-PLAZA.x-pose.x,p.z-PLAZA.z-pose.z)>Math.max(f.w,f.d)*.6||p.ragdoll)return;entry.lastBounce=now;this.game.broadcast({type:'plaza-bounce',playerId:p.id,itemId:item.id,at:now,velocity:Number.isFinite(m.velocity)?Math.max(0,Math.min(12,m.velocity)):6.5});}
 receive(entry,m,now){const p=entry.player,error=text=>this.game.broadcast({type:'plaza-play-error',playerId:p.id,error:text});if(m.action==='stop'){this.stop(p.id);return;}if(p.ragdoll||this.game.duel?.ids.includes(p.id))return;
  const item=this.game.houses.snapshots().plaza?.items.find(i=>i.id===m.itemId),f=item&&FURNITURE_BY_ID.get(item.t);if(f?.family!=='playground'||['slide','trampoline'].includes(f.design))return;const current=this.sessions.get(p.id);
  if(m.action==='start'){if(now-(entry.lastPlazaStart||0)<500)return;entry.lastPlazaStart=now;const pose=furniturePose(item);if(Math.hypot(p.x-PLAZA.x-pose.x,p.z-PLAZA.z-pose.z)>Math.max(3,Math.hypot(f.w,f.d)*.55+1))return;this.prune(now);const used=new Set([...this.sessions.values()].filter(s=>s.itemId===item.id&&s.playerId!==p.id).map(s=>s.slot||0)),capacity=f.design==='carousel'?4:f.id==='play-double-swing'||f.design==='seesaw'?2:1,slot=Array.from({length:capacity},(_,i)=>i).find(i=>!used.has(i));if(slot===undefined){error('ほかの人が遊んでいます。少し待ってください');return;}this.stop(p.id);const state={type:'plaza-play-state',active:true,playerId:p.id,itemId:item.id,kind:f.design,slot,startedAt:now,updatedAt:now,input:0,progress:0,angle:0,angularVelocity:0,lift:false};this.sessions.set(p.id,state);this.game.broadcast(state);return;}
  if(m.action==='input'&&current?.itemId===item.id){if(now-(current.lastInputAt||0)<150)return;current.lastInputAt=now;const pose=furniturePose(item);if(Math.hypot(p.x-PLAZA.x-pose.x,p.z-PLAZA.z-pose.z)>Math.hypot(f.w,f.d)+4){this.stop(p.id);return;}current.updatedAt=now;current.input=Number.isFinite(m.input)?Math.max(-1,Math.min(1,m.input)):0;current.progress=Number.isFinite(m.progress)?Math.max(0,Math.min(1,m.progress)):0;current.lift=m.lift===true;current.inputX=Number.isFinite(m.inputX)?Math.max(-1,Math.min(1,m.inputX)):0;current.charge=Number.isFinite(m.charge)?Math.max(0,Math.min(2.5,m.charge)):0;
   if(current.kind==='seesaw'){const riders=[...this.sessions.values()].filter(s=>s.itemId===item.id),target=riders.length===2?((riders.find(s=>s.slot===0)?.lift?1:0)-(riders.find(s=>s.slot===1)?.lift?1:0))*.28:0;for(const r of riders){r.fromAngle=r.angle||0;r.angle=target;r.waiting=riders.length!==2;r.updatedAt=now;this.game.broadcast({...r});}return;}
   if(current.kind==='carousel'){const riders=[...this.sessions.values()].filter(s=>s.itemId===item.id),motion=this.motions.get(item.id)||{angle:0,angularVelocity:0,at:now},dt=Math.min(.4,Math.max(0,(now-motion.at)/1000));motion.angularVelocity=Math.max(-3,Math.min(3,motion.angularVelocity+(riders.reduce((n,r)=>n+r.inputX,0)*1.4-motion.angularVelocity*.18)*dt));motion.angle+=motion.angularVelocity*dt;motion.at=now;this.motions.set(item.id,motion);for(const r of riders){r.angle=motion.angle;r.angularVelocity=motion.angularVelocity;r.updatedAt=now;this.game.broadcast({...r});}return;}
   current.angle=Number.isFinite(m.angle)?Math.max(-1e6,Math.min(1e6,m.angle)):0;current.angularVelocity=Number.isFinite(m.angularVelocity)?Math.max(-6.8,Math.min(6.8,m.angularVelocity)):0;this.game.broadcast({...current});}
 }
}
